    private static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web);
    private static async Task<IResult> Write<T>(HttpContext ctx, AtomicExecutor executor, ISecrets secrets, T body, Func<Task<object?>> action, bool idempotent = false, int status = 200)
    {
        var key = ctx.Request.Headers["Idempotency-Key"].FirstOrDefault(); if (idempotent && key == null) throw new RuleException("VALIDATION_ERROR", "Thiếu Idempotency-Key.", 400);
        var result = await executor.Run(ctx.User.Identity?.IsAuthenticated == true ? ctx.Actor().Id : "public:" + ctx.Connection.RemoteIpAddress, ctx.Request.Path, key, secrets.Hash(JsonSerializer.Serialize(body, Json)), action, status, ctx.RequestAborted);
        return Results.Text(result.Json, "application/json", statusCode: result.Status);
    }
    public static void MapGrapEndpoints(this WebApplication app)
    {
        var api = app.MapGroup("/api/v1");
        api.MapGet("/app-config", () => new { currency = "VND", timezone = "Asia/Ho_Chi_Minh", environment = app.Environment.EnvironmentName, featureFlags = new { cash = true, onlinePayments = false, promotions = false, payouts = false, savedPlaces = true, trustedContacts = true, accountDeletionRequests = true, privateDocumentUpload = app.Environment.IsDevelopment(), push = app.Services.GetRequiredService<IPushSender>().Enabled, demoMaps = app.Environment.IsDevelopment() && app.Configuration["Maps:BaseUrl"] == null }, services = new[] { new { code = "BIKE", name = "GrapBike", seats = 1 }, new { code = "CAR_4", name = "GrapCar 4 chỗ", seats = 4 }, new { code = "CAR_7", name = "GrapCar 7 chỗ", seats = 7 } }, serverTime = DateTime.UtcNow });
        if (app.Environment.IsDevelopment())
        {
            api.MapGet("/auth/development/accounts", (GrapDbContext db) => db.Set<User>().Where(u => u.Status == "ACTIVE").Select(u => new { u.Id, u.Name, u.Role }).ToList());
            api.MapPost("/auth/development", (DevelopmentLogin body, HttpContext ctx, AtomicExecutor executor, GrapDbContext db, ISecrets secrets, RideService service, IConfiguration config) => Write(ctx, executor, secrets, body, async () => { var user = service.Find<User>(body.UserId); var (session, token) = Identity.NewSession(user, body.DeviceId, secrets); db.Add(session); await db.SaveChangesAsync(); return Identity.Issue(user, session, token, config); })).RequireRateLimiting("auth");
        }
        api.MapPost("/auth/otp/challenges", async (OtpChallengeRequest body, GrapDbContext db, ISecrets secrets, IOtpProvider sms, CancellationToken ct) =>
        {
            var phone = body.Phone.Trim().Replace(" ", ""); if (phone.StartsWith('0')) phone = "+84" + phone[1..]; if (!Regex.IsMatch(phone, @"^\+[1-9]\d{8,14}$") || body.AppType is not ("customer" or "driver")) throw new RuleException("VALIDATION_ERROR", "Số điện thoại hoặc loại ứng dụng không hợp lệ.", 400);
            if (await db.Set<OtpChallenge>().AnyAsync(o => o.Phone == phone && o.CreatedAt > DateTime.UtcNow.AddSeconds(-60), ct)) throw new RuleException("RATE_LIMITED", "Vui lòng đợi 60 giây trước khi gửi lại.", 429);
            var code = RandomNumberGenerator.GetInt32(100000, 1000000).ToString(); var challenge = new OtpChallenge { Phone = phone, AppType = body.AppType, CodeHmac = secrets.Hmac(code) }; await sms.Send(phone, code, ct); db.Add(challenge); await db.SaveChangesAsync(ct); return Results.Created("/api/v1/auth/otp/challenges/" + challenge.Id, new { challengeId = challenge.Id, challenge.ExpiresAt, resendAfter = 60, serverTime = DateTime.UtcNow });
        }).RequireRateLimiting("auth");
        api.MapPost("/auth/otp/verify", (OtpVerifyRequest body, HttpContext ctx, AtomicExecutor executor, GrapDbContext db, ISecrets secrets, RideService service, IConfiguration config) => Write(ctx, executor, secrets, body, async () =>
        {
            var challenge = service.Find<OtpChallenge>(body.ChallengeId); if (challenge.ConsumedAt != null || challenge.ExpiresAt <= DateTime.UtcNow || challenge.Attempts >= 5) throw new RuleException("OTP_EXPIRED", "Mã xác minh đã hết hạn hoặc bị khóa.", 422);
            if (secrets.Hmac(body.Otp) != challenge.CodeHmac) { challenge.Attempts++; throw new RuleException("OTP_INVALID", "Mã xác minh không đúng.", 422, persist: true); }
            challenge.ConsumedAt = DateTime.UtcNow; var user = db.Set<User>().SingleOrDefault(u => u.Phone == challenge.Phone); if (user == null) { user = new User { Phone = challenge.Phone, Name = "Thành viên Grap", Role = challenge.AppType == "driver" ? Roles.Driver : Roles.Customer }; db.Add(user); if (user.Role == Roles.Driver) db.Add(new Driver { UserId = user.Id }); }
            if (user.Status != "ACTIVE" || user.Role != (challenge.AppType == "driver" ? Roles.Driver : Roles.Customer)) throw new RuleException("FORBIDDEN", "Tài khoản không khả dụng trong ứng dụng này.", 403);
            var (session, token) = Identity.NewSession(user, body.DeviceId, secrets); db.Add(session); await db.SaveChangesAsync(); return Identity.Issue(user, session, token, config);
        })).RequireRateLimiting("auth");
        api.MapPost("/auth/token/refresh", (RefreshRequest body, HttpContext ctx, AtomicExecutor executor, GrapDbContext db, ISecrets secrets, RideService service, IConfiguration config) => Write(ctx, executor, secrets, body, async () =>
        {
            var hash = secrets.Hash(body.RefreshToken); var old = db.Set<Session>().SingleOrDefault(s => s.RefreshHash == hash) ?? throw new RuleException("SESSION_EXPIRED", "Phiên đã hết hạn.", 401);
            if (old.RevokedAt != null) { foreach (var session in db.Set<Session>().Where(s => s.Family == old.Family)) session.RevokedAt = DateTime.UtcNow; throw new RuleException("TOKEN_REUSE", "Phiên đã được thu hồi. Vui lòng đăng nhập lại.", 401, persist: true); }
            var user = service.Find<User>(old.UserId); if (old.ExpiresAt <= DateTime.UtcNow || user.Status != "ACTIVE") throw new RuleException("SESSION_EXPIRED", "Phiên đã hết hạn.", 401);
            old.RevokedAt = DateTime.UtcNow; var (next, token) = Identity.NewSession(user, old.DeviceId, secrets, old.Family); db.Add(next); var driver = db.Set<Driver>().SingleOrDefault(d => d.UserId == user.Id); if (driver?.ActiveSessionId == old.Id) driver.ActiveSessionId = next.Id;
            foreach (var device in db.Set<PushDevice>().Where(d => d.SessionId == old.Id && d.RevokedAt == null)) device.SessionId = next.Id;
            foreach (var delivery in db.Set<PushDelivery>().Where(d => d.SessionId == old.Id && d.Status == "PENDING")) delivery.SessionId = next.Id;
            await db.SaveChangesAsync(); return Identity.Issue(user, next, token, config);
        })).RequireRateLimiting("auth");
        var auth = api.MapGroup("").RequireAuthorization();
        auth.MapPost("/auth/logout", (HttpContext ctx, GrapDbContext db, AtomicExecutor executor, ISecrets secrets) => Write(ctx, executor, secrets, new { }, async () => { var actor = ctx.Actor(); var session = await db.Set<Session>().FindAsync(actor.SessionId); if (session != null) session.RevokedAt = DateTime.UtcNow; foreach (var device in db.Set<PushDevice>().Where(d => d.SessionId == actor.SessionId && d.RevokedAt == null)) { device.RevokedAt = DateTime.UtcNow; device.TokenProtected = ""; } var driver = db.Set<Driver>().SingleOrDefault(d => d.UserId == actor.Id && d.ActiveSessionId == actor.SessionId); if (driver != null) { driver.Online = false; driver.ActiveSessionId = null; } return new { success = true }; }));
        auth.MapGet("/me", (HttpContext ctx, RideService service) => { var user = service.Find<User>(ctx.Actor().Id); return new { user.Id, user.Name, user.Role, user.Email, phone = RideService.Mask(user.Phone), user.ZoneId, user.Version }; });
        auth.MapPatch("/me/profile", (ProfileRequest body, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService service) => Write(ctx, executor, secrets, body, () => { var user = service.Find<User>(ctx.Actor().Id); if (user.Version != body.ExpectedVersion) throw new RuleException("VERSION_CONFLICT", "Hồ sơ đã thay đổi."); if (string.IsNullOrWhiteSpace(body.Name) || body.Name.Length > 100 || body.Email?.Length > 200 || !string.IsNullOrWhiteSpace(body.Email) && !System.Net.Mail.MailAddress.TryCreate(body.Email, out _)) throw new RuleException("VALIDATION_ERROR", "Thông tin hồ sơ không hợp lệ.", 400); user.Name = body.Name.Trim(); user.Email = string.IsNullOrWhiteSpace(body.Email) ? null : body.Email.Trim(); user.Version++; return Task.FromResult<object?>(new { user.Id, user.Name, user.Email, user.Version }); }));
        auth.MapGet("/places/autocomplete", async (string? q, IMapProvider maps, CancellationToken ct) =>
        {
            if (q?.Length > 150) throw new RuleException("VALIDATION_ERROR", "Từ khóa tối đa 150 ký tự.", 400);
            return new { items = await maps.Search(q?.Trim() ?? "", ct), source = maps is DemoMapProvider ? "DEVELOPMENT_FIXTURE" : "CONFIGURED_PROVIDER" };
        });
        auth.MapGet("/customers/me/nearby-services", (double latitude, double longitude, HttpContext ctx, RideService service) =>
            service.Nearby(ctx.Actor(), new(latitude, longitude, "Điểm đón")));
        auth.MapGet("/service-zones/availability", (GrapDbContext db) => new { items = db.Set<ServiceZone>().Where(z => z.Active).ToList() });
        auth.MapPost("/quotes", async (QuoteRequest body, HttpContext ctx, RideService service, GrapDbContext db, CancellationToken ct) => { var quote = await service.CreateQuote(ctx.Actor(), body, ct); await db.SaveChangesAsync(ct); return Results.Created("/api/v1/quotes/" + quote.Id, new { quoteId = quote.Id, quote.Fare, estimatedDistanceMeters = quote.DistanceMeters, estimatedDurationSeconds = quote.DurationSeconds, quote.ExpiresAt, quote.FarePolicyVersion, quote.RouteSource, serverTime = DateTime.UtcNow }); });
        auth.MapPost("/rides", (RideRequest body, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService service, GrapDbContext db) => Write(ctx, executor, secrets, body, async () => { var ride = service.CreateRide(ctx.Actor(), body); await db.SaveChangesAsync(); return service.Snapshot(ctx.Actor(), ride); }, true, 201));
        auth.MapGet("/rides/active", (HttpContext ctx, GrapDbContext db, RideService service) => { var actor = ctx.Actor(); actor.Require(Roles.Customer, Roles.Driver); var driverId = actor.Role == Roles.Driver ? service.DriverFor(actor).Id : ""; var ride = db.Set<Ride>().FirstOrDefault(r => RideStates.Active.Contains(r.Status) && (r.CustomerId == actor.Id || r.DriverId == driverId)); return new { ride = ride == null ? null : service.Snapshot(actor, ride), serverTime = DateTime.UtcNow }; });
        auth.MapGet("/rides", (HttpContext ctx, GrapDbContext db, RideService service, ISecrets secrets, string? status, string? cursor, int? pageSize, DateTimeOffset? from, DateTimeOffset? to) => RideHistory(ctx, db, service, secrets, status, cursor, pageSize, from, to));
        auth.MapGet("/rides/{id}", (string id, HttpContext ctx, RideService service) => service.Snapshot(ctx.Actor(), service.AuthorizedRide(ctx.Actor(), id)));
        auth.MapGet("/rides/{id}/events", (string id, HttpContext ctx, RideService service, GrapDbContext db) => { service.AuthorizedRide(ctx.Actor(), id); return new { items = db.Set<RideEvent>().Where(e => e.RideId == id).OrderBy(e => e.Sequence).ToList() }; });
        auth.MapGet("/rides/{id}/receipt", (string id, HttpContext ctx, RideService service) => service.Snapshot(ctx.Actor(), service.AuthorizedRide(ctx.Actor(), id)));
        auth.MapPost("/rides/{id}/cancel-preview", (string id, HttpContext ctx, RideService service) => { var ride = service.AuthorizedRide(ctx.Actor(), id); return new { fee = 0, currency = "VND", ride.Version, expiresAt = DateTime.UtcNow.AddSeconds(60) }; });
        foreach (var command in new[] { "arrive", "start", "complete", "cancel", "release-assignment", "no-show" })
            auth.MapPost("/rides/{id}/" + command, (string id, RideCommand body, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService service, GrapDbContext db) => Write(ctx, executor, secrets, body, async () => { var ride = service.Command(ctx.Actor(), id, command, body); await db.SaveChangesAsync(); return service.Snapshot(ctx.Actor(), ride); }, true));
        auth.MapGet("/rides/{id}/payment", (string id, HttpContext ctx, RideService service, GrapDbContext db) => { service.AuthorizedRide(ctx.Actor(), id); var p = db.Set<Payment>().SingleOrDefault(p => p.RideId == id); return new { payment = p, remainingAmount = p?.PayableAmount - p?.PaidAmount }; });
        auth.MapPost("/payments/{id}/cash-collections", (string id, CashRequest body, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService service) => Write(ctx, executor, secrets, body, () => Task.FromResult<object?>(service.Collect(ctx.Actor(), id, body)), true));
        MapDriver(auth); MapSupport(auth); MapAdmin(auth); MapSafety(api, auth); MapFiles(auth); MapCustomerFeatures(auth); MapReceiptFeatures(auth); MapPush(auth); MapStatistics(auth);
        auth.MapGet("/notifications", (HttpContext ctx, GrapDbContext db) => new { items = db.Set<Notification>().Where(n => n.UserId == ctx.Actor().Id).OrderByDescending(n => n.CreatedAt).Take(100).ToList() });
        auth.MapPost("/notifications/{id}/read", (string id, HttpContext ctx, GrapDbContext db, RideService service, AtomicExecutor executor, ISecrets secrets) => Write(ctx, executor, secrets, new { id }, () => { var notification = service.Find<Notification>(id); if (notification.UserId != ctx.Actor().Id) throw new RuleException("RESOURCE_NOT_FOUND", "Không tìm thấy thông báo.", 404); notification.ReadAt ??= DateTime.UtcNow; return Task.FromResult<object?>(notification); }));
    }
    private static object Page<T>(IEnumerable<T> source, string? cursor, int? pageSize)
    {
        var take = Math.Clamp(pageSize ?? 20, 1, 100); var offset = 0; if (cursor != null && (!int.TryParse(cursor, out offset) || offset < 0)) throw new RuleException("VALIDATION_ERROR", "Cursor không hợp lệ.", 400);
        var items = source.Skip(offset).Take(take + 1).ToList(); var more = items.Count > take; return new { items = items.Take(take), nextCursor = more ? (offset + take).ToString() : null, hasMore = more, serverTime = DateTime.UtcNow };
    }
    private static void MapDriver(RouteGroupBuilder auth)
    {
        auth.MapGet("/drivers/me/application", (HttpContext ctx, RideService s) => s.DriverFor(ctx.Actor()));
        auth.MapPut("/drivers/me/application", (DriverApplicationRequest body, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService s) => Write(ctx, executor, secrets, body, () => { var d = s.DriverFor(ctx.Actor()); if (d.ReviewStatus is not ("DRAFT" or "REJECTED") || d.Version != body.ExpectedVersion) throw new RuleException("VERSION_CONFLICT", "Chỉ sửa hồ sơ nháp hoặc hồ sơ cần bổ sung với phiên bản mới nhất."); if (body.ServiceTypeCode is not ("BIKE" or "CAR_4" or "CAR_7") || string.IsNullOrWhiteSpace(body.Plate) || body.Plate.Length > 20 || string.IsNullOrWhiteSpace(body.Vehicle) || body.Vehicle.Length > 100 || string.IsNullOrWhiteSpace(body.Color) || body.Color.Length > 30) throw new RuleException("VALIDATION_ERROR", "Cần thông tin xe hợp lệ.", 400); d.Plate = body.Plate.Trim().ToUpperInvariant(); d.Vehicle = body.Vehicle.Trim(); d.Color = body.Color.Trim(); d.ServiceTypeCode = body.ServiceTypeCode; d.ReviewStatus = "DRAFT"; d.Version++; return Task.FromResult<object?>(d); }));
        auth.MapGet("/drivers/me/availability", (HttpContext ctx, RideService s, GrapDbContext db) => { var d = s.DriverFor(ctx.Actor()); return new { online = d.Online, d.OfflineAfterRide, d.ReviewStatus, d.Version, d.HeartbeatAt, d.LocationAt, busy = db.Set<Assignment>().Any(a => a.DriverId == d.Id && a.EndedAt == null), deviceActive = d.ActiveSessionId == ctx.Actor().SessionId, serverTime = DateTime.UtcNow }; });
        auth.MapPost("/drivers/me/availability", (AvailabilityRequest body, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService s, GrapDbContext db) => Write(ctx, executor, secrets, body, () =>
        {
            var actor = ctx.Actor(); var d = s.DriverFor(actor); if (d.Version != body.ExpectedVersion) throw new RuleException("VERSION_CONFLICT", "Trạng thái tài xế đã thay đổi.", 409, d.Version);
            if (body.Online && (d.ReviewStatus != "APPROVED" || d.DocumentsExpireAt <= DateTime.UtcNow || d.DocumentsExpireAt == null)) throw new RuleException("DRIVER_NOT_APPROVED", "Hồ sơ hoặc giấy tờ chưa đủ điều kiện.", 403);
            if (body.Online && d.ActiveSessionId != null && d.ActiveSessionId != actor.SessionId && db.Set<Session>().Any(session => session.Id == d.ActiveSessionId && session.RevokedAt == null && session.ExpiresAt > DateTime.UtcNow)) throw new RuleException("DEVICE_ALREADY_ACTIVE", "Tài xế đang hoạt động trên thiết bị khác. Đăng xuất thiết bị đó trước.");
            var busy = db.Set<Assignment>().Any(a => a.DriverId == d.Id && a.EndedAt == null); if (!body.Online && busy) d.OfflineAfterRide = true; else { d.Online = body.Online; d.OfflineAfterRide = false; }
            if (body.Online) { if (d.ActiveSessionId != actor.SessionId) { d.LocationSequence = 0; d.LocationAt = null; d.HeartbeatAt = null; } d.ActiveSessionId = actor.SessionId; }
            if (!body.Online && !busy) foreach (var o in db.Set<Offer>().Where(o => o.DriverId == d.Id && o.Status == "OPEN")) { o.Status = "REVOKED"; o.Version++; }
            d.Version++; return Task.FromResult<object?>(new { d.Online, d.OfflineAfterRide, d.Version });
        }));
        auth.MapPost("/drivers/me/heartbeat", (HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService s) => Write(ctx, executor, secrets, new { }, () => { var d = s.DriverFor(ctx.Actor()); if (d.ActiveSessionId != ctx.Actor().SessionId) throw new RuleException("SESSION_EXPIRED", "Thiết bị không còn hoạt động.", 403); d.HeartbeatAt = DateTime.UtcNow; return Task.FromResult<object?>(new { serverTime = DateTime.UtcNow }); }));
        auth.MapPost("/drivers/me/location-batches", (LocationBatch body, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService s, GrapDbContext db) => Write(ctx, executor, secrets, body, () =>
        {
            var d = s.DriverFor(ctx.Actor()); if (d.ActiveSessionId != ctx.Actor().SessionId || body.Samples.Length > 100 || body.Samples.Length == 0) throw new RuleException("VALIDATION_ERROR", "Thiết bị hoặc batch không hợp lệ.", 400);
            var accepted = 0; var inBatch = new HashSet<string>();
            foreach (var sample in body.Samples.OrderBy(x => x.Sequence))
            {
                var sampleId = sample.SampleId ?? sample.Sequence.ToString();
                if (sampleId.Length > 100 || !inBatch.Add(sampleId) || db.Set<LocationSample>().Any(s => s.DriverId == d.Id && s.SessionId == ctx.Actor().SessionId && s.SampleId == sampleId) || sample.AccuracyMeters is <= 0 or > 100 || sample.Sequence < 1 || sample.RecordedAt > DateTime.UtcNow.AddSeconds(15) || sample.RecordedAt < DateTime.UtcNow.AddMinutes(-30) || !double.IsFinite(sample.Latitude) || !double.IsFinite(sample.Longitude) || sample.Latitude is < -90 or > 90 || sample.Longitude is < -180 or > 180) continue;
                db.Add(new LocationSample { DriverId = d.Id, SessionId = ctx.Actor().SessionId, SampleId = sampleId, Sequence = sample.Sequence, Latitude = sample.Latitude, Longitude = sample.Longitude, AccuracyMeters = sample.AccuracyMeters, RecordedAt = sample.RecordedAt }); accepted++;
                if (sample.Sequence <= d.LocationSequence || sample.RecordedAt < d.LocationAt) continue;
                d.Latitude = sample.Latitude; d.Longitude = sample.Longitude; d.Accuracy = sample.AccuracyMeters; d.LocationSequence = sample.Sequence; d.LocationAt = sample.RecordedAt;
            }
            var activeRide = db.Set<Ride>().SingleOrDefault(r => r.DriverId == d.Id && RideStates.Active.Contains(r.Status));
            if (accepted > 0 && activeRide != null) db.Add(new OutboxMessage { AggregateId = activeRide.Id, AggregateVersion = activeRide.Version, EventType = "ride.driver.location.updated", Payload = System.Text.Json.JsonSerializer.Serialize(new { rideId = activeRide.Id, locationSequence = d.LocationSequence, d.LocationAt }) });
            return Task.FromResult<object?>(new { accepted, rejected = body.Samples.Length - accepted, latestSequence = d.LocationSequence, serverTime = DateTime.UtcNow });
        }));
        auth.MapGet("/drivers/me/offers/current", (HttpContext ctx, GrapDbContext db, RideService s) => { var actor = ctx.Actor(); var d = s.DriverFor(actor); var offer = d.ActiveSessionId == actor.SessionId ? db.Set<Offer>().SingleOrDefault(o => o.DriverId == d.Id && o.Status == "OPEN" && o.ExpiresAt > DateTime.UtcNow) : null; var ride = offer == null ? null : s.Find<Ride>(offer.RideId); return new { offer = offer == null ? null : new { offerId = offer.Id, offer.Version, offer.ExpiresAt, rideId = ride!.Id, ride.Pickup, ride.ServiceTypeCode, customerPayable = ride.Fare.CustomerPayable, driverEntitlement = ride.Fare.GrossFare - ride.Fare.PlatformCommission }, serverTime = DateTime.UtcNow }; });
        auth.MapPost("/driver-offers/{id}/accept", (string id, VersionRequest body, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService s, GrapDbContext db) => Write(ctx, executor, secrets, body, async () => { var ride = s.Accept(ctx.Actor(), id, body.ExpectedVersion); await db.SaveChangesAsync(); return s.Snapshot(ctx.Actor(), ride); }, true));
        auth.MapPost("/driver-offers/{id}/reject", (string id, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService s) => Write(ctx, executor, secrets, new { id }, () => { s.Reject(ctx.Actor(), id); return Task.FromResult<object?>(new { success = true }); }));
        auth.MapGet("/drivers/me/balance", (HttpContext ctx, RideService s) => s.Balance(s.DriverFor(ctx.Actor()).Id));
        auth.MapPost("/rides/{id}/contact-attempts", (string id, ContactAttemptRequest body, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService service, GrapDbContext db) => Write(ctx, executor, secrets, body, () =>
        {
            var driver = service.DriverFor(ctx.Actor()); var ride = service.AuthorizedRide(ctx.Actor(), id);
            RideStates.Require(ride.Status, "ASSIGNED", "DRIVER_ARRIVED");
            if (ride.DriverId != driver.Id || !db.Set<Assignment>().Any(a => a.RideId == id && a.DriverId == driver.Id && a.EndedAt == null)) throw new RuleException("FORBIDDEN", "Chỉ tài xế hiện hành được ghi nhận liên hệ.", 403);
            if (body.Channel is not ("PHONE" or "MESSAGE")) throw new RuleException("VALIDATION_ERROR", "Kênh liên hệ không hợp lệ.", 400);
            RideService.RequireReason(body.Note); var attempt = new RideContactAttempt { RideId = id, DriverId = driver.Id, Channel = body.Channel, Note = body.Note }; db.Add(attempt); return Task.FromResult<object?>(new { attempt.Id, attempt.CreatedAt });
        }, true, 201));
        auth.MapGet("/drivers/me/earnings", (HttpContext ctx, GrapDbContext db, RideService s) => { var d = s.DriverFor(ctx.Actor()); var rides = db.Set<Ride>().Where(r => r.DriverId == d.Id && r.Status == "COMPLETED").ToList(); return new { completedRides = rides.Count, grossFare = rides.Sum(r => r.Fare.GrossFare), commission = rides.Sum(r => r.Fare.PlatformCommission), entitlement = rides.Sum(r => r.Fare.GrossFare - r.Fare.PlatformCommission), balance = s.Balance(d.Id), items = rides.OrderByDescending(r => r.CreatedAt).Take(30).Select(r => s.Snapshot(ctx.Actor(), r)), currency = "VND" }; });
    }
    private static void MapSupport(RouteGroupBuilder auth)
    {
        auth.MapGet("/support/tickets", (HttpContext ctx, GrapDbContext db) => new { items = db.Set<SupportTicket>().Where(t => t.RequesterId == ctx.Actor().Id).OrderByDescending(t => t.CreatedAt).ToList() });
        auth.MapPost("/support/tickets", (TicketRequest body, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, GrapDbContext db, RideService s) => Write(ctx, executor, secrets, body, () => { if (body.Subject.Length < 5 || body.Subject.Length > 200 || body.Message.Length < 5 || body.Message.Length > 5000) throw new RuleException("VALIDATION_ERROR", "Tiêu đề hoặc nội dung không hợp lệ.", 400); if (body.RideId != null) s.AuthorizedRide(ctx.Actor(), body.RideId); var ticket = new SupportTicket { RequesterId = ctx.Actor().Id, Subject = body.Subject, Category = body.Category, RideId = body.RideId, Priority = body.Priority is "HIGH" or "URGENT" ? body.Priority : "NORMAL" }; db.Add(ticket); db.Add(new TicketMessage { TicketId = ticket.Id, AuthorId = ctx.Actor().Id, Body = body.Message }); return Task.FromResult<object?>(ticket); }, status: 201));
        auth.MapGet("/support/tickets/{id}", (string id, HttpContext ctx, RideService s, GrapDbContext db) => { var t = s.Find<SupportTicket>(id); TicketAccess(ctx.Actor(), t); return new { ticket = t, messages = db.Set<TicketMessage>().Where(m => m.TicketId == id).OrderBy(m => m.CreatedAt).ToList() }; });
        auth.MapPost("/support/tickets/{id}/messages", (string id, MessageRequest body, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, GrapDbContext db, RideService s) => Write(ctx, executor, secrets, body, () => { var t = s.Find<SupportTicket>(id); TicketAccess(ctx.Actor(), t); if (t.Status == "CLOSED") throw new RuleException("TICKET_CLOSED", "Yêu cầu đã đóng. Vui lòng tạo yêu cầu mới hoặc nhờ hỗ trợ mở lại."); if (body.Body.Length < 1 || body.Body.Length > 5000) throw new RuleException("VALIDATION_ERROR", "Nội dung từ 1 đến 5.000 ký tự.", 400); var m = new TicketMessage { TicketId = id, AuthorId = ctx.Actor().Id, Body = body.Body }; db.Add(m); if (ctx.Actor().Id != t.RequesterId) db.Add(new Notification { UserId = t.RequesterId, Kind = "ticket", EntityId = t.Id, Title = "Hỗ trợ đã phản hồi", Body = "Yêu cầu hỗ trợ của bạn có cập nhật mới." }); return Task.FromResult<object?>(m); }));
    }
    private static void TicketAccess(Actor actor, SupportTicket ticket) { actor.Scope(ticket.ZoneId); if (actor.Id != ticket.RequesterId && !(actor.Role == Roles.Security && ticket.Category == "ACCOUNT_DELETION")) actor.Require(Roles.Support, Roles.Operations); }
    private static void MapSafety(RouteGroupBuilder api, RouteGroupBuilder auth)
    {
        auth.MapPost("/rides/{id}/ratings", (string id, RatingRequest body, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService s, GrapDbContext db) => Write(ctx, executor, secrets, body, () => { var ride = s.AuthorizedRide(ctx.Actor(), id); ctx.Actor().Require(Roles.Customer, Roles.Driver); if (ride.Status != "COMPLETED" || body.Stars is < 1 or > 5 || body.Comment?.Length > 1000) throw new RuleException("VALIDATION_ERROR", "Chỉ đánh giá chuyến hoàn tất với 1–5 sao.", 400); if (ride.EndedAt == null || ride.EndedAt <= DateTime.UtcNow.AddDays(-1)) throw new RuleException("RATING_WINDOW_CLOSED", "Đã hết thời hạn 24 giờ để đánh giá hoặc sửa đánh giá."); var rating = db.Set<Rating>().SingleOrDefault(r => r.RideId == id && r.AuthorId == ctx.Actor().Id); if (rating == null) { rating = new Rating { RideId = id, AuthorId = ctx.Actor().Id }; db.Add(rating); } else if (rating.CreatedAt < DateTime.UtcNow.AddDays(-1)) throw new RuleException("RATING_WINDOW_CLOSED", "Đã hết hạn sửa đánh giá."); rating.Stars = body.Stars; rating.Comment = body.Comment; return Task.FromResult<object?>(rating); }));
        auth.MapPost("/rides/{id}/share-tokens", (string id, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService s, GrapDbContext db) => Write(ctx, executor, secrets, new { id }, () => { var ride = s.AuthorizedRide(ctx.Actor(), id); if (ride.CustomerId != ctx.Actor().Id || !RideStates.IsActive(ride.Status)) throw new RuleException("FORBIDDEN", "Chỉ chủ chuyến đang hoạt động được chia sẻ.", 403); var token = Convert.ToHexString(RandomNumberGenerator.GetBytes(32)); var share = new ShareToken { RideId = id, TokenHash = secrets.Hash(token), ExpiresAt = DateTime.UtcNow.AddHours(2) }; db.Add(share); return Task.FromResult<object?>(new { share.Id, token, share.ExpiresAt }); }));
        auth.MapDelete("/rides/{id}/share-tokens/{tokenId}", (string id, string tokenId, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService s) => Write(ctx, executor, secrets, new { id, tokenId }, () => { var ride = s.AuthorizedRide(ctx.Actor(), id); var token = s.Find<ShareToken>(tokenId); if (ride.CustomerId != ctx.Actor().Id || token.RideId != id) throw new RuleException("RESOURCE_NOT_FOUND", "Không tìm thấy liên kết.", 404); token.RevokedAt = DateTime.UtcNow; return Task.FromResult<object?>(new { success = true }); }));
        api.MapGet("/public/ride-shares/{token}", (string token, GrapDbContext db, ISecrets secrets, RideService s, HttpContext ctx) => { ctx.Response.Headers["X-Robots-Tag"] = "noindex, nofollow"; var hash = secrets.Hash(token); var share = db.Set<ShareToken>().SingleOrDefault(t => t.TokenHash == hash && t.RevokedAt == null && t.ExpiresAt > DateTime.UtcNow) ?? throw new RuleException("RESOURCE_NOT_FOUND", "Liên kết không còn hiệu lực.", 404); var ride = s.Find<Ride>(share.RideId); if (!RideStates.IsActive(ride.Status)) throw new RuleException("SHARE_ENDED", "Chuyến đi đã kết thúc.", 410); var driver = ride.DriverId == null ? null : s.Find<Driver>(ride.DriverId); return new { ride.Code, ride.Status, ride.Pickup, ride.Dropoff, location = driver == null ? null : new { driver.Latitude, driver.Longitude, driver.LocationAt }, share.ExpiresAt }; });
        auth.MapPost("/rides/{id}/safety-incidents", (string id, HttpContext ctx, AtomicExecutor executor, ISecrets secrets, RideService s, GrapDbContext db) => Write(ctx, executor, secrets, new { id }, () => { var ride = s.AuthorizedRide(ctx.Actor(), id); ctx.Actor().Require(Roles.Customer, Roles.Driver); if (!RideStates.IsActive(ride.Status)) throw new RuleException("INVALID_RIDE_STATE", "Chuyến không còn hoạt động."); var incident = new SafetyIncident { RideId = id, ReporterId = ctx.Actor().Id }; db.Add(incident); db.Add(new SupportTicket { RequesterId = ctx.Actor().Id, RideId = id, Subject = "SOS · " + ride.Code, Category = "SAFETY", Priority = "URGENT" }); return Task.FromResult<object?>(new { incident.Id, incident.Status, message = "Hệ thống đã lưu cảnh báo. Chưa có nhân sự xác nhận tiếp nhận." }); }, status: 201));
    }
}
public record VersionRequest(int ExpectedVersion);
public record ProfileRequest(int ExpectedVersion, string Name, string? Email);
public record DriverApplicationRequest(int ExpectedVersion, string ServiceTypeCode, string Plate, string Vehicle, string Color);
public record AvailabilityRequest(int ExpectedVersion, bool Online);
public record LocationBatch(LocationEvidence[] Samples);
public record MessageRequest(string Body);
public record RatingRequest(int Stars, string? Comment);
public record ContactAttemptRequest(string Channel, string Note);
